CREATE TABLE users (
 id uuid PRIMARY KEY, email text UNIQUE, password_hash text, display_name text NOT NULL,
 status text NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','SUSPENDED','WITHDRAWN')),
 email_verified_at timestamptz, staff_scopes text[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid REFERENCES users(id), csrf_token text NOT NULL, idle_expires_at timestamptz NOT NULL, absolute_expires_at timestamptz NOT NULL, revoked_at timestamptz);
CREATE TABLE auth_tokens (token_hash text PRIMARY KEY, user_id uuid REFERENCES users(id), purpose text NOT NULL, context jsonb NOT NULL DEFAULT '{}', expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE oauth_identities (user_id uuid NOT NULL REFERENCES users(id), provider text NOT NULL, provider_subject text NOT NULL, PRIMARY KEY(provider,provider_subject), UNIQUE(user_id,provider));
CREATE TABLE consents (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), document_type text NOT NULL, document_version text NOT NULL, agreed_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE school_verifications (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), method text NOT NULL, affiliation_type text NOT NULL, state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','VERIFIED','REJECTED','EXPIRED','REVOKED')), evidence_media_id uuid, expires_at timestamptz, reason text, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_verified ON school_verifications(user_id) WHERE state='VERIFIED';
CREATE UNIQUE INDEX one_verification_pending ON school_verifications(user_id) WHERE state='PENDING';
CREATE TABLE profiles (id uuid PRIMARY KEY, user_id uuid UNIQUE NOT NULL REFERENCES users(id), headline text NOT NULL DEFAULT '', bio text NOT NULL DEFAULT '', visibility text NOT NULL DEFAULT 'PRIVATE' CHECK(visibility IN ('PRIVATE','PUBLIC')), availability text NOT NULL DEFAULT 'AVAILABLE' CHECK(availability IN ('AVAILABLE','BUSY')), field_ids text[] NOT NULL DEFAULT '{}', skill_ids text[] NOT NULL DEFAULT '{}', avatar_media_id uuid, version integer NOT NULL DEFAULT 1);
CREATE TABLE categories (id text PRIMARY KEY, label text NOT NULL, position integer NOT NULL);
CREATE TABLE service_fields (id text PRIMARY KEY, category_id text NOT NULL REFERENCES categories(id), label text NOT NULL, group_label text NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE skills (id text PRIMARY KEY, label text NOT NULL, aliases text[] NOT NULL DEFAULT '{}');
CREATE TABLE field_skills (field_id text REFERENCES service_fields(id), skill_id text REFERENCES skills(id), PRIMARY KEY(field_id,skill_id));
CREATE TABLE careers (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), body jsonb NOT NULL, version integer NOT NULL DEFAULT 1);
CREATE TABLE offered_services (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), body jsonb NOT NULL, version integer NOT NULL DEFAULT 1);
CREATE TABLE portfolios (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), visibility text NOT NULL DEFAULT 'PRIVATE' CHECK(visibility IN ('PRIVATE','PUBLIC')), current_version_id uuid, published_version_id uuid, version integer NOT NULL DEFAULT 1, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE portfolio_versions (id uuid PRIMARY KEY, portfolio_id uuid NOT NULL REFERENCES portfolios(id), revision_no integer NOT NULL, body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(portfolio_id,revision_no), UNIQUE(portfolio_id,id));
ALTER TABLE portfolios ADD FOREIGN KEY(id,current_version_id) REFERENCES portfolio_versions(portfolio_id,id);
ALTER TABLE portfolios ADD FOREIGN KEY(id,published_version_id) REFERENCES portfolio_versions(portfolio_id,id);
CREATE TABLE featured_portfolios (user_id uuid NOT NULL REFERENCES users(id), portfolio_id uuid NOT NULL REFERENCES portfolios(id), position integer NOT NULL CHECK(position BETWEEN 0 AND 2), PRIMARY KEY(user_id,portfolio_id), UNIQUE(user_id,position));
CREATE TABLE projects (id uuid PRIMARY KEY, owner_id uuid NOT NULL REFERENCES users(id), terms jsonb NOT NULL DEFAULT '{}', closes_at timestamptz, visibility text NOT NULL DEFAULT 'PUBLIC' CHECK(visibility IN ('PUBLIC','DIRECT_ONLY')), status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','OPEN','CLOSED','MATCHED','IN_PROGRESS','COMPLETION_REQUESTED','COMPLETED','CANCELLED')), current_revision_id uuid, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE project_revisions (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), revision_no integer NOT NULL, terms jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,revision_no), UNIQUE(project_id,id));
ALTER TABLE projects ADD FOREIGN KEY(id,current_revision_id) REFERENCES project_revisions(project_id,id);
CREATE TABLE proposals (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), applicant_id uuid NOT NULL REFERENCES users(id), status text NOT NULL DEFAULT 'SUBMITTED' CHECK(status IN ('SUBMITTED','IN_DISCUSSION','SELECTED','WITHDRAWN','REJECTED')), current_revision_id uuid, rejection_reason text, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,applicant_id));
CREATE TABLE proposal_revisions (id uuid PRIMARY KEY, proposal_id uuid NOT NULL REFERENCES proposals(id), revision_no integer NOT NULL, project_revision_id uuid NOT NULL REFERENCES project_revisions(id), amount bigint NOT NULL CHECK(amount>0 AND amount<=1000000000), days integer NOT NULL CHECK(days BETWEEN 1 AND 365), content text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(proposal_id,revision_no), UNIQUE(proposal_id,id));
ALTER TABLE proposals ADD FOREIGN KEY(id,current_revision_id) REFERENCES proposal_revisions(proposal_id,id);
CREATE TABLE proposal_portfolio_snapshots (proposal_revision_id uuid NOT NULL REFERENCES proposal_revisions(id), portfolio_version_id uuid NOT NULL REFERENCES portfolio_versions(id), explicit_share boolean NOT NULL, metadata jsonb NOT NULL, PRIMARY KEY(proposal_revision_id,portfolio_version_id));
CREATE TABLE direct_requests (id uuid PRIMARY KEY, sender_id uuid NOT NULL REFERENCES users(id), recipient_id uuid NOT NULL REFERENCES users(id), status text NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','ACCEPTED','REJECTED','CANCELLED','EXPIRED')), expires_at timestamptz NOT NULL, latest_terms_id uuid, accepted_terms_id uuid, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now(), CHECK(sender_id<>recipient_id));
CREATE TABLE direct_request_terms (id uuid PRIMARY KEY, direct_request_id uuid NOT NULL REFERENCES direct_requests(id), revision_no integer NOT NULL, kind text NOT NULL CHECK(kind IN ('ORIGINAL','QUOTE')), author_id uuid NOT NULL REFERENCES users(id), terms jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(direct_request_id,revision_no), UNIQUE(direct_request_id,id));
ALTER TABLE direct_requests ADD FOREIGN KEY(id,latest_terms_id) REFERENCES direct_request_terms(direct_request_id,id);
ALTER TABLE direct_requests ADD FOREIGN KEY(id,accepted_terms_id) REFERENCES direct_request_terms(direct_request_id,id);
CREATE TABLE matches (id uuid PRIMARY KEY, project_id uuid UNIQUE NOT NULL REFERENCES projects(id), provider_id uuid NOT NULL REFERENCES users(id), proposal_revision_id uuid REFERENCES proposal_revisions(id), direct_request_id uuid UNIQUE REFERENCES direct_requests(id), direct_terms_id uuid REFERENCES direct_request_terms(id), agreed_terms jsonb NOT NULL, CHECK((proposal_revision_id IS NOT NULL AND direct_request_id IS NULL AND direct_terms_id IS NULL) OR (proposal_revision_id IS NULL AND direct_request_id IS NOT NULL AND direct_terms_id IS NOT NULL)));
CREATE TABLE conversations (id uuid PRIMARY KEY, project_id uuid REFERENCES projects(id), applicant_id uuid REFERENCES users(id), direct_request_id uuid UNIQUE REFERENCES direct_requests(id), next_sequence integer NOT NULL DEFAULT 0, UNIQUE(project_id,applicant_id), CHECK((project_id IS NOT NULL AND applicant_id IS NOT NULL AND direct_request_id IS NULL) OR (project_id IS NULL AND applicant_id IS NULL AND direct_request_id IS NOT NULL)));
CREATE TABLE conversation_members (conversation_id uuid REFERENCES conversations(id), user_id uuid REFERENCES users(id), last_read_sequence integer NOT NULL DEFAULT 0 CHECK(last_read_sequence>=0), PRIMARY KEY(conversation_id,user_id));
CREATE TABLE messages (id uuid PRIMARY KEY, conversation_id uuid NOT NULL REFERENCES conversations(id), sender_id uuid REFERENCES users(id), client_message_id uuid, source_event_id uuid, sequence integer NOT NULL, kind text NOT NULL CHECK(kind IN ('USER','SYSTEM')), text text NOT NULL CHECK(char_length(text)<=3000), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(conversation_id,sequence), UNIQUE(conversation_id,sender_id,client_message_id), UNIQUE(conversation_id,source_event_id));
CREATE TABLE workrooms (id uuid PRIMARY KEY, project_id uuid UNIQUE NOT NULL REFERENCES projects(id), match_id uuid UNIQUE NOT NULL REFERENCES matches(id), conversation_id uuid UNIQUE NOT NULL REFERENCES conversations(id));
CREATE TABLE contracts (id uuid PRIMARY KEY, workroom_id uuid UNIQUE NOT NULL REFERENCES workrooms(id), signed_version_id uuid, review_version_id uuid, version integer NOT NULL DEFAULT 1);
CREATE TABLE contract_versions (id uuid PRIMARY KEY, contract_id uuid NOT NULL REFERENCES contracts(id), sequence integer NOT NULL, author_id uuid NOT NULL REFERENCES users(id), base_signed_version_id uuid REFERENCES contract_versions(id), status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','WAITING_ACCEPTANCE','SIGNED','SUPERSEDED','CANCELLED')), body jsonb NOT NULL, content_hash text, document_media_id uuid, document_status text NOT NULL DEFAULT 'PENDING', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(contract_id,sequence), UNIQUE(contract_id,id));
ALTER TABLE contracts ADD FOREIGN KEY(id,signed_version_id) REFERENCES contract_versions(contract_id,id);
ALTER TABLE contracts ADD FOREIGN KEY(id,review_version_id) REFERENCES contract_versions(contract_id,id);
CREATE TABLE contract_acceptances (contract_version_id uuid REFERENCES contract_versions(id), user_id uuid REFERENCES users(id), content_hash text NOT NULL, accepted_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(contract_version_id,user_id));
CREATE TABLE completion_requests (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), requester_id uuid NOT NULL REFERENCES users(id), contract_version_id uuid NOT NULL REFERENCES contract_versions(id), state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','APPROVED','CHANGES_REQUESTED','CANCELLED')), note text NOT NULL, reason text, decided_by uuid REFERENCES users(id), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_completion_pending ON completion_requests(project_id) WHERE state='PENDING';
CREATE TABLE cancellation_requests (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), requester_id uuid NOT NULL REFERENCES users(id), state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','APPROVED','REJECTED','WITHDRAWN')), reason text NOT NULL, decided_by uuid REFERENCES users(id), version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_cancellation_pending ON cancellation_requests(project_id) WHERE state='PENDING';
CREATE TABLE reviews (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), author_id uuid NOT NULL REFERENCES users(id), subject_id uuid NOT NULL REFERENCES users(id), subject_role text NOT NULL CHECK(subject_role IN ('PROVIDER','REQUESTER')), rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), body text NOT NULL, visibility text NOT NULL DEFAULT 'PUBLIC', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,author_id), CHECK(author_id<>subject_id));
CREATE TABLE publication_approvals (id uuid PRIMARY KEY, project_id uuid NOT NULL REFERENCES projects(id), portfolio_version_id uuid NOT NULL REFERENCES portfolio_versions(id), requester_id uuid NOT NULL REFERENCES users(id), state text NOT NULL DEFAULT 'PENDING_APPROVAL' CHECK(state IN ('PENDING_APPROVAL','APPROVED','REJECTED','CANCELLED')), decided_by uuid REFERENCES users(id), version integer NOT NULL DEFAULT 1, UNIQUE(project_id,portfolio_version_id));
CREATE TABLE media_objects (id uuid PRIMARY KEY, owner_id uuid REFERENCES users(id), filename text NOT NULL, object_key text UNIQUE NOT NULL, ready_key text, mime text NOT NULL, size bigint NOT NULL CHECK(size>0), checksum text, state text NOT NULL DEFAULT 'UPLOADING' CHECK(state IN ('UPLOADING','SCANNING','READY','REJECTED','EXPIRED','DELETING','DELETED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE uploads (id uuid PRIMARY KEY, media_id uuid UNIQUE NOT NULL REFERENCES media_objects(id), purpose text NOT NULL, target_id uuid, token_hash text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE media_links (media_id uuid REFERENCES media_objects(id), target_type text NOT NULL, target_id uuid NOT NULL, linked_by uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(media_id,target_type,target_id));
ALTER TABLE school_verifications ADD FOREIGN KEY(evidence_media_id) REFERENCES media_objects(id);
ALTER TABLE profiles ADD FOREIGN KEY(avatar_media_id) REFERENCES media_objects(id);
ALTER TABLE contract_versions ADD FOREIGN KEY(document_media_id) REFERENCES media_objects(id);
CREATE TABLE favorites (user_id uuid REFERENCES users(id), target_type text NOT NULL CHECK(target_type IN ('projects','experts','portfolios')), target_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,target_type,target_id));
CREATE TABLE outbox_events (id uuid PRIMARY KEY, type text NOT NULL, aggregate_id uuid NOT NULL, aggregate_version integer NOT NULL, recipients uuid[] NOT NULL, data jsonb NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), dispatched_at timestamptz);
CREATE TABLE jobs (id uuid PRIMARY KEY, event_id uuid REFERENCES outbox_events(id), handler text NOT NULL, dedup_key text NOT NULL, state text NOT NULL DEFAULT 'PENDING', payload jsonb NOT NULL, attempts integer NOT NULL DEFAULT 0, next_run_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, last_error text, UNIQUE(handler,dedup_key));
CREATE TABLE processed_events (consumer text NOT NULL, event_id uuid NOT NULL, PRIMARY KEY(consumer,event_id));
CREATE TABLE recipient_streams (user_id uuid PRIMARY KEY REFERENCES users(id), last_sequence bigint NOT NULL DEFAULT 0);
CREATE TABLE user_events (recipient_id uuid REFERENCES users(id), sequence bigint NOT NULL, event_id uuid NOT NULL REFERENCES outbox_events(id), type text NOT NULL, data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(recipient_id,sequence), UNIQUE(recipient_id,event_id));
CREATE TABLE notifications (id uuid PRIMARY KEY, recipient_id uuid NOT NULL REFERENCES users(id), event_id uuid NOT NULL REFERENCES outbox_events(id), type text NOT NULL, target_ref jsonb NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(recipient_id,event_id));
CREATE TABLE idempotency_records (actor_id uuid REFERENCES users(id), method text NOT NULL, path text NOT NULL, key text NOT NULL, body_hash text NOT NULL, response jsonb, expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours', PRIMARY KEY(actor_id,method,path,key));
CREATE TABLE support_tickets (id uuid PRIMARY KEY, requester_id uuid NOT NULL REFERENCES users(id), subject text NOT NULL, status text NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ticket_replies (id uuid PRIMARY KEY, ticket_id uuid NOT NULL REFERENCES support_tickets(id), author_id uuid NOT NULL REFERENCES users(id), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reports (id uuid PRIMARY KEY, reporter_id uuid NOT NULL REFERENCES users(id), project_id uuid REFERENCES projects(id), target_type text NOT NULL, target_id uuid NOT NULL, reason text NOT NULL, status text NOT NULL DEFAULT 'OPEN', dispute_active boolean NOT NULL DEFAULT false, version integer NOT NULL DEFAULT 1, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs (id uuid PRIMARY KEY, actor_id uuid REFERENCES users(id), action text NOT NULL, target_id uuid, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX projects_public ON projects(visibility,status,created_at,id);
CREATE INDEX projects_owner ON projects(owner_id,created_at);
CREATE INDEX proposals_applicant ON proposals(applicant_id,created_at);
CREATE INDEX requests_recipient ON direct_requests(recipient_id,status);
CREATE INDEX notifications_recipient ON notifications(recipient_id,created_at);
CREATE INDEX jobs_ready ON jobs(state,next_run_at);
CREATE INDEX outbox_pending ON outbox_events(occurred_at) WHERE dispatched_at IS NULL;
CREATE INDEX media_target ON media_links(target_type,target_id);
CREATE OR REPLACE FUNCTION preserve_revision() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable revision' USING ERRCODE='23514'; END $$;
CREATE TRIGGER immutable_project_revision BEFORE UPDATE OR DELETE ON project_revisions FOR EACH ROW EXECUTE FUNCTION preserve_revision();
CREATE TRIGGER immutable_proposal_revision BEFORE UPDATE OR DELETE ON proposal_revisions FOR EACH ROW EXECUTE FUNCTION preserve_revision();
CREATE TRIGGER immutable_direct_terms BEFORE UPDATE OR DELETE ON direct_request_terms FOR EACH ROW EXECUTE FUNCTION preserve_revision();
CREATE TRIGGER immutable_portfolio_version BEFORE UPDATE OR DELETE ON portfolio_versions FOR EACH ROW EXECUTE FUNCTION preserve_revision();
CREATE OR REPLACE FUNCTION preserve_contract() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.status <> 'DRAFT' AND (NEW.body IS DISTINCT FROM OLD.body OR NEW.content_hash IS DISTINCT FROM OLD.content_hash) THEN RAISE EXCEPTION 'immutable published contract' USING ERRCODE='23514'; END IF;
 IF OLD.status='SIGNED' AND NEW.status <> 'SIGNED' THEN RAISE EXCEPTION 'immutable signed state' USING ERRCODE='23514'; END IF;
 RETURN NEW;
 END $$;
CREATE TRIGGER immutable_contract_body BEFORE UPDATE ON contract_versions FOR EACH ROW EXECUTE FUNCTION preserve_contract();
